import styled from '@emotion/styled';
import { StyledBlackTooltipContainer } from 'shared/Styles';
import { theme } from 'theme';

export const StyledGanttChartHeaderTitle = styled.div({
  fontFamily: theme.fonts.paragraph,
  fontWeight: 500,
  fontSize: '14px',
  borderRight: '1px solid #14141414',
  display: 'flex',
  flex: 1,
  justifyContent: 'center',
  textAlign: 'center',
  color: theme.colors.txt.default,
  alignItems: 'center',
  gap: '10px',
});

export const StyledGanttChartCellContainer = styled.div({
  display: 'flex',
  borderBottom: '1px solid #14141414',
});

export const StyledGanttHeaderTooltip = styled(StyledBlackTooltipContainer)({
  zIndex: 99999,
  width: 256,
  height: 92,
  maxWidth: 256,
  maxHeight: 108,
  whiteSpace: 'normal',
  overflowWrap: 'break-word',
  wordBreak: 'break-word',
  position: 'static',
});

interface StyledGanttHeaderCellProps {
  $lastCell?: boolean;
}

export const StyledGanttHeaderCell = styled.div<StyledGanttHeaderCellProps>(
  ({ $lastCell }) => ({
    fontFamily: theme.fonts.paragraph,
    fontWeight: 400,
    fontSize: '10px',
    border: '1px solid #14141414',
    position: 'relative',
    zIndex: 1,
    borderLeft: 'none',
    borderBottom: 'none',
    borderRight: `1px solid ${theme.colors.gray[30]}`,
    padding: `${theme.spacing['05']} ${theme.spacing['1']}`,
    color: theme.colors.txt.secondary,
    flex: 1,
    textAlign: 'center',
    ...($lastCell && {
      borderRight: '1px solid #14141414',
    }),
  }),
);

export const StyledGanttHeader = styled.div({
  display: 'flex',
  flexDirection: 'column',
  backgroundColor: '#ffffffff',
  flex: 1,
});
